from __future__ import annotations

from api.operator_console_runner_control import CONSOLE_HTML_V39

EVIDENCE_RETURN_SCRIPT = r"""
<style>
.evidence-return{margin-top:14px;background:#fff;border:1px solid #dce9f8;border-radius:18px;padding:18px;box-shadow:0 12px 34px rgba(11,47,97,.05)}.evidence-note{padding:12px;border:1px solid #cfe7d8;background:#f2fbf5;border-radius:10px;color:#147a46;margin-bottom:10px}.evidence-warn{padding:12px;border:1px solid #f2dfb8;background:#fff8ea;border-radius:10px;color:#7c4b00;margin-bottom:10px}.evidence-confirm{display:flex;gap:9px;align-items:flex-start;padding:12px;border:1px solid #e2edf8;background:#fbfdff;border-radius:10px}.evidence-return button{width:100%;margin-top:10px;border:0;border-radius:10px;padding:12px;background:#1769e0;color:#fff;font-weight:900;cursor:pointer}.evidence-return button:disabled{opacity:.5;cursor:not-allowed}.evidence-status{min-height:20px;margin-top:10px;font-size:13px}.evidence-status.ok{color:#147a46}.evidence-status.err{color:#b42318}
</style>
<script>
async function loadEvidenceReturnControl(recordId){const view=document.getElementById('view');if(!view||!recordId)return;let box=document.getElementById('evidence-return-control');if(!box){box=document.createElement('section');box.id='evidence-return-control';box.className='evidence-return';const timeline=view.querySelector('.timeline');if(timeline)view.insertBefore(box,timeline);else view.appendChild(box)}box.innerHTML='<h3>Return Execution Result as Evidence</h3><div class="muted">Checking latest execution receipt…</div>';try{const r=await fetch('/operator/api/cases/'+encodeURIComponent(recordId)+'/evidence-return-context',{credentials:'same-origin'});if(r.status===401){location.href='/operator/login';return}if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.detail||'evidence return context unavailable')}const d=await r.json();if(!d.ready){box.innerHTML=`<h3>Return Execution Result as Evidence</h3><div class="muted">Not available: ${esc((d.reason||'not ready').replaceAll('_',' '))}</div>`;return}const e=d.execution;box.innerHTML=`<h3>Return Execution Result as Evidence</h3><div class="evidence-note">Completed read: <strong>${esc(e.capability_id)} / ${esc(e.operation)}</strong> · HTTP ${esc(e.http_status??'n/a')}<br>Result SHA-256: ${esc(d.receipt_integrity.result_sha256)}</div><div class="evidence-warn">This creates one immutable evidence-return packet in the originating review lineage. It does not refresh the decision, approve anything, or start another cycle automatically.</div><label class="evidence-confirm"><input type="checkbox" id="evidence-confirm"><span>I want to return this exact completed read result as evidence for human review.</span></label><button id="evidence-return-button">Return result as evidence</button><div id="evidence-status" class="evidence-status"></div>`;box.querySelector('#evidence-return-button').onclick=async()=>{const status=box.querySelector('#evidence-status');const btn=box.querySelector('#evidence-return-button');status.textContent='';status.className='evidence-status';if(!box.querySelector('#evidence-confirm').checked){status.textContent='Explicit evidence-return confirmation is required.';status.className='evidence-status err';return}btn.disabled=true;try{const csrf=await loadConsoleCsrf();const rr=await fetch('/operator/api/read-only-executions/'+encodeURIComponent(e.execution_receipt_id)+'/evidence-return',{method:'POST',headers:{'content-type':'application/json','x-vmi-csrf':csrf},credentials:'same-origin',body:JSON.stringify({confirm_return_evidence:true})});if(!rr.ok){const x=await rr.json().catch(()=>({}));throw new Error(x.detail||'Evidence return rejected')}const x=await rr.json();status.textContent=`Evidence return ${x.evidence_return.evidence_return_id} recorded. Decision refresh created automatically: false.`;status.className='evidence-status ok';setTimeout(()=>loadCase(recordId),350)}catch(err){status.textContent=String(err.message||err);status.className='evidence-status err'}finally{btn.disabled=false}}}catch(err){box.innerHTML=`<h3>Return Execution Result as Evidence</h3><div class="muted">${esc(err.message||'Unavailable.')}</div>`}}
const _v39LoadCase=loadCase;loadCase=async function(id){await _v39LoadCase(id);await loadEvidenceReturnControl(id)};setTimeout(()=>{if(selected)loadEvidenceReturnControl(selected)},1900);
</script>
"""

CONSOLE_HTML_V40 = CONSOLE_HTML_V39.replace("</body>", EVIDENCE_RETURN_SCRIPT + "</body>")
